//! Rendering reads validated projection decisions only.

use std::fmt::Write;

use super::ir::*;

fn literal(value: &str) -> String {
    serde_json::to_string(value).expect("string is serializable")
}

pub(super) fn javascript(file: &File) -> String {
    let mut text = format!(
        "// Generated by dynwinrt-codegen\n'use strict';\n// Contract-validated flat Win32 subset; omitted exports are not supported.\nconst {{ Win32CallPlan }} = require({});\n",
        literal(&file.unsafe_import),
    );
    for (index, function) in file.functions.iter().enumerate() {
        let args = function
            .inputs
            .iter()
            .map(|i| i.name.as_str())
            .collect::<Vec<_>>()
            .join(", ");
        let descriptor = literal(&serde_json::to_string(&function.plan).expect("validated plan"));
        writeln!(text, "let _plan{index};").unwrap();
        writeln!(text, "function {}({args}) {{", function.name).unwrap();
        writeln!(
            text,
            "  if (arguments.length !== {}) throw new TypeError('Expected {} arguments');",
            function.inputs.len(),
            function.inputs.len()
        )
        .unwrap();
        writeln!(
            text,
            "  const result = (_plan{index} ??= Win32CallPlan.bind({descriptor})).invoke([{args}]);"
        )
        .unwrap();
        if function.outputs.is_empty() {
            writeln!(text, "  return result.value;").unwrap();
        } else {
            let fields = function
                .outputs
                .iter()
                .enumerate()
                .map(|(i, output)| format!("{}: result.outputs[{i}]", literal(&output.name)))
                .collect::<Vec<_>>()
                .join(", ");
            writeln!(text, "  return {{ status: result.value, {fields} }};").unwrap();
        }
        writeln!(text, "}}\nexports.{} = {};", function.name, function.name).unwrap();
    }
    text
}

pub(super) fn declarations(file: &File) -> String {
    let mut text = format!(
        "// Generated by dynwinrt-codegen\n// Contract-validated flat Win32 subset; omitted exports are not supported.\nimport type {{ Win32Handle, Win32Resource }} from {};\n",
        literal(&file.safe_import),
    );
    for function in &file.functions {
        let inputs = function
            .inputs
            .iter()
            .map(|input| {
                let typ = match input.typ {
                    InputType::U32 => "number",
                    InputType::Utf16 { nullable: true } => "string | null",
                    InputType::Utf16 { nullable: false } => "string",
                    InputType::Hkey => "Win32Handle | Win32Resource",
                    InputType::Resource => "Win32Resource",
                    InputType::OptionalBytes => "Buffer | Uint8Array | null",
                };
                format!("{}: {typ}", input.name)
            })
            .collect::<Vec<_>>()
            .join(", ");
        let result = if function.outputs.is_empty() {
            match function.plan.returns {
                ReturnKind::U32 | ReturnKind::Status => "number".into(),
                ReturnKind::U64 => "bigint".into(),
            }
        } else {
            let fields = function
                .outputs
                .iter()
                .map(|output| {
                    let typ = match output.typ {
                        OutputType::U32 => "number | null",
                        OutputType::Hkey => "Win32Handle | Win32Resource | null",
                        OutputType::Bytes => "Buffer | null",
                    };
                    format!("{}: {typ}", output.name)
                })
                .collect::<Vec<_>>()
                .join("; ");
            format!("{{ status: number; {fields} }}")
        };
        if function
            .inputs
            .iter()
            .any(|i| matches!(i.typ, InputType::OptionalBytes))
        {
            writeln!(text, "/** null probes the required size. Buffers supply capacity; bytes are privately staged and returned, never written into the input. ERROR_MORE_DATA preserves the required size, not undefined data. */").unwrap();
        }
        writeln!(
            text,
            "export declare function {}({inputs}): {result};",
            function.name
        )
        .unwrap();
    }
    text
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn win32_renderer_uses_only_projected_decisions() {
        let file = File {
            safe_import: "@example/runtime/win32".into(),
            unsafe_import: "@example/runtime/win32/unsafe".into(),
            functions: vec![Function {
                name: "example".into(),
                plan: Plan {
                    version: 1,
                    dll: "EXAMPLE.dll".into(),
                    entry_point: "UnrelatedNativeName".into(),
                    calling_convention: "system",
                    architectures: 7,
                    returns: ReturnKind::Status,
                    parameters: vec![
                        Argument::BorrowHkey {
                            reject_performance_data: true,
                        },
                        Argument::Bytes { count_parameter: 2 },
                        Argument::ByteCount {
                            buffer_parameter: 1,
                        },
                    ],
                },
                inputs: vec![
                    Input {
                        name: "key".into(),
                        typ: InputType::Hkey,
                    },
                    Input {
                        name: "bytes".into(),
                        typ: InputType::OptionalBytes,
                    },
                ],
                outputs: vec![
                    Output {
                        name: "data".into(),
                        typ: OutputType::Bytes,
                    },
                    Output {
                        name: "size".into(),
                        typ: OutputType::U32,
                    },
                ],
            }],
        };
        let js = javascript(&file);
        assert!(js.starts_with("// Generated by dynwinrt-codegen\n"));
        assert!(js.contains("function example(key, bytes)"));
        assert!(js.contains("\"size\": result.outputs[1]"));
        assert!(!js.contains(".byteLength"));
        assert!(!js.contains(".length)"));
        let dts = declarations(&file);
        assert!(dts.starts_with("// Generated by dynwinrt-codegen\n"));
        assert!(dts.contains("key: Win32Handle | Win32Resource"));
        assert!(dts.contains("data: Buffer | null; size: number | null"));
    }
}
